27	/// Runs the Flutter tool with support for the specified list of [commands].
28	Future<int> run(
29	  List<String> args,
30	  List<FlutterCommand> commands, {
31	  bool muteCommandLogging = false,
32	  bool verbose = false,
33	  bool verboseHelp = false,
34	  bool reportCrashes,
35	  String flutterVersion,
36	  Map<Type, Generator> overrides,
37	}) {
38	  reportCrashes ??= !isRunningOnBot;
39	
40	  if (muteCommandLogging) {
41	    // Remove the verbose option; for help and doctor, users don't need to see
42	    // verbose logs.
43	    args = List<String>.from(args);
44	    args.removeWhere((String option) => option == '-v' || option == '--verbose');
45	  }
46	
47	  final FlutterCommandRunner runner = FlutterCommandRunner(verboseHelp: verboseHelp);
48	  commands.forEach(runner.addCommand);
49	
50	  return runInContext<int>(() async {
51	    // Initialize the system locale.
52	    final String systemLocale = await intl_standalone.findSystemLocale();
53	    intl.Intl.defaultLocale = intl.Intl.verifiedLocale(
54	      systemLocale, intl.NumberFormat.localeExists,
55	      onFailure: (String _) => 'en_US',
56	    );
57	
58	    String getVersion() => flutterVersion ?? FlutterVersion.instance.getVersionString(redactUnknownBranches: true);
59	    Object firstError;
60	    StackTrace firstStackTrace;
61	    return await runZoned<Future<int>>(() async {
62	      try {
63	        await runner.run(args);
64	        return await _exit(0);
65	      } catch (error, stackTrace) {
66	        firstError = error;
67	        firstStackTrace = stackTrace;
68	        return await _handleToolError(
69	            error, stackTrace, verbose, args, reportCrashes, getVersion);
70	      }
71	    }, onError: (Object error, StackTrace stackTrace) async {
72	      // If sending a crash report throws an error into the zone, we don't want
73	      // to re-try sending the crash report with *that* error. Rather, we want
74	      // to send the original error that triggered the crash report.
75	      final Object e = firstError ?? error;
76	      final StackTrace s = firstStackTrace ?? stackTrace;
77	      await _handleToolError(e, s, verbose, args, reportCrashes, getVersion);
78	    });
79	  }, overrides: overrides);
80	}
