82	Future<int> _handleToolError(
83	  dynamic error,
84	  StackTrace stackTrace,
85	  bool verbose,
86	  List<String> args,
87	  bool reportCrashes,
88	  String getFlutterVersion(),
89	) async {
90	  if (error is UsageException) {
91	    printError('${error.message}\n');
92	    printError("Run 'flutter -h' (or 'flutter <command> -h') for available flutter commands and options.");
93	    // Argument error exit code.
94	    return _exit(64);
95	  } else if (error is ToolExit) {
96	    if (error.message != null) {
97	      printError(error.message);
98	    }
99	    if (verbose) {
100	      printError('\n$stackTrace\n');
101	    }
102	    return _exit(error.exitCode ?? 1);
103	  } else if (error is ProcessExit) {
104	    // We've caught an exit code.
105	    if (error.immediate) {
106	      exit(error.exitCode);
107	      return error.exitCode;
108	    } else {
109	      return _exit(error.exitCode);
110	    }
111	  } else {
112	    // We've crashed; emit a log report.
113	    stderr.writeln();
114	
115	    if (!reportCrashes) {
116	      // Print the stack trace on the bots - don't write a crash report.
117	      stderr.writeln('$error');
118	      stderr.writeln(stackTrace.toString());
119	      return _exit(1);
120	    }
121	
122	    // Report to both [Usage] and [CrashReportSender].
123	    flutterUsage.sendException(error);
124	    await CrashReportSender.instance.sendReport(
125	      error: error,
126	      stackTrace: stackTrace,
127	      getFlutterVersion: getFlutterVersion,
128	      command: args.join(' '),
129	    );
130	
131	    if (error is String) {
132	      stderr.writeln('Oops; flutter has exited unexpectedly: "$error".');
133	    } else {
134	      stderr.writeln('Oops; flutter has exited unexpectedly.');
135	    }
136	
137	    try {
138	      final File file = await _createLocalCrashReport(args, error, stackTrace);
139	      stderr.writeln(
140	        'Crash report written to ${file.path};\n'
141	            'please let us know at https://github.com/flutter/flutter/issues.',
142	      );
143	      return _exit(1);
144	    } catch (error) {
145	      stderr.writeln(
146	        'Unable to generate crash report due to secondary error: $error\n'
147	            'please let us know at https://github.com/flutter/flutter/issues.',
148	      );
149	      // Any exception throw here (including one thrown by `_exit()`) will
150	      // get caught by our zone's `onError` handler. In order to avoid an
151	      // infinite error loop, we throw an error that is recognized above
152	      // and will trigger an immediate exit.
153	      throw ProcessExit(1, immediate: true);
154	    }
155	  }
156	}
